import React, { useState, useEffect } from 'react';
import api from '../api';

const AdminFleetMonitor = ({ showToast }) => {
    const [devices, setDevices] = useState([]);
    const [users, setUsers] = useState([]);

    const loadData = async () => {
        try {
            const [devRes, usrRes] = await Promise.all([api.get('/admin/devices'), api.get('/admin/users')]);
            setDevices(devRes.data);
            setUsers(usrRes.data);
        } catch (err) {
            showToast('Admin access required to view fleet telemetry.', 'error');
        }
    };

    useEffect(() => {
        loadData();
    }, []);

    const toggleDevice = async (id) => {
        try {
            const res = await api.post(`/admin/devices/${id}/toggle`);
            setDevices(devices.map(d => (d.id === id ? res.data : d)));
            showToast(`${res.data.name} is now ${res.data.online ? 'ONLINE' : 'OFFLINE'}.`, res.data.online ? 'success' : 'warning');
        } catch (err) {
            showToast('Failed to toggle device state', 'error');
        }
    };

    const approvePayout = async (id) => {
        try {
            const res = await api.post(`/admin/users/${id}/payout`);
            showToast(res.data.message, 'success');
            loadData();
        } catch (err) {
            showToast('Payout failed', 'error');
        }
    };

    return (
        <div className="space-y-6">
            <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
                <div className="p-5 sm:p-6 border-b border-slate-800 flex flex-wrap items-center justify-between gap-4">
                    <div>
                        <h2 className="text-lg font-bold text-white">Autonomous IoT Gate Fleet Telemetry</h2>
                        <p className="text-xs text-slate-400">Toggle Raspberry Pi 4 &amp; ESP32 gate availability in real time.</p>
                    </div>
                    <span className="px-3 py-1 rounded-full text-xs font-mono bg-cyan-500/15 text-cyan-300 border border-cyan-500/30">MQTT / HTTPS Heartbeat: 5s</span>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                        <tr className="bg-slate-950/70 text-[11px] font-mono uppercase tracking-wider text-slate-400 border-b border-slate-800">
                            <th className="py-3.5 px-5">Device / Gate Name</th>
                            <th className="py-3.5 px-5">Hardware &amp; MAC ID</th>
                            <th className="py-3.5 px-5">Assigned Venue</th>
                            <th className="py-3.5 px-5">Scans Processed</th>
                            <th className="py-3.5 px-5">Last Heartbeat</th>
                            <th className="py-3.5 px-5 text-right">Power / Online State</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/70 text-sm">
                        {devices.map(dev => (
                            <tr key={dev.id} className="hover:bg-slate-850/60 transition">
                                <td className="py-3.5 px-5 font-bold text-white flex items-center gap-2.5">
                                    <span className={`w-2.5 h-2.5 rounded-full ${dev.online ? 'bg-emerald-400 animate-pulse' : 'bg-rose-500'}`}></span>
                                    <span>{dev.name}</span>
                                </td>
                                <td className="py-3.5 px-5 font-mono text-xs text-slate-300">{dev.hardwareMac}</td>
                                <td className="py-3.5 px-5 text-slate-300 text-xs">{dev.venue}</td>
                                <td className="py-3.5 px-5 font-mono font-bold text-cyan-300">{dev.scansProcessed}</td>
                                <td className="py-3.5 px-5 font-mono text-xs text-slate-400">{dev.online ? dev.lastHeartbeat : 'Disconnected'}</td>
                                <td className="py-3.5 px-5 text-right">
                                    <button onClick={() => toggleDevice(dev.id)} className={`px-3 py-1.5 rounded-lg text-xs font-mono font-bold transition ${dev.online ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 hover:bg-rose-500/20 hover:text-rose-300' : 'bg-rose-500/20 text-rose-300 border border-rose-500/40 hover:bg-emerald-500/20 hover:text-emerald-300'}`}>
                                        {dev.online ? 'ONLINE (Click to Disable)' : 'OFFLINE (Click to Boot)'}
                                    </button>
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
                <div className="p-5 sm:p-6 border-b border-slate-800">
                    <h3 className="text-lg font-bold text-white">Platform Accounts &amp; Organizer Financial Payouts</h3>
                    <p className="text-xs text-slate-400">Spring Security RBAC users &amp; live organizer balance settlements.</p>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                        <tr className="bg-slate-950/70 text-[11px] font-mono uppercase tracking-wider text-slate-400 border-b border-slate-800">
                            <th className="py-3.5 px-5">Account Name</th>
                            <th className="py-3.5 px-5">Email</th>
                            <th className="py-3.5 px-5">RBAC Role</th>
                            <th className="py-3.5 px-5">Net Balance</th>
                            <th className="py-3.5 px-5 text-right">Settlement Action</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/70 text-sm">
                        {users.map(u => (
                            <tr key={u.id}>
                                <td className="py-3.5 px-5 font-semibold text-white">{u.fullName}</td>
                                <td className="py-3.5 px-5 font-mono text-xs text-slate-400">{u.email}</td>
                                <td className="py-3.5 px-5">
                                    <span className="px-2.5 py-0.5 rounded-full text-xs font-mono bg-indigo-500/20 text-indigo-300">{u.role}</span>
                                </td>
                                <td className="py-3.5 px-5 font-mono text-emerald-400 font-bold">
                                    {u.role === 'ORGANIZER' ? `${Number(u.netBalance).toLocaleString()} RON` : '—'}
                                </td>
                                <td className="py-3.5 px-5 text-right">
                                    {u.role === 'ORGANIZER' && Number(u.netBalance) > 0 ? (
                                        <button onClick={() => approvePayout(u.id)} className="px-3 py-1.5 rounded-lg bg-emerald-500/15 hover:bg-emerald-500/25 text-emerald-300 border border-emerald-500/30 text-xs font-semibold transition">
                                            Approve Payout
                                        </button>
                                    ) : (
                                        <span className="text-xs font-mono text-slate-500">Settled / Verified</span>
                                    )}
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default AdminFleetMonitor;
